<dialog x-ref="onuToolDialog" class="onu-tool-dialog" aria-labelledby="onu-tool-title" @cancel.prevent="closeOnuTool()" @click="if($event.target===$refs.onuToolDialog)closeOnuTool()">
    <template x-if="toolTarget"><div class="onu-tool-shell">
        <header class="onu-tool-header">
            <div class="onu-tool-heading"><button class="btn secondary" @click="closeOnuTool()" :disabled="toolApplying"><i data-lucide="arrow-left"></i>Kembali</button><div><span class="onu-tool-badge"><i data-lucide="settings-2"></i>ONU Configuration Tool</span><h2 id="onu-tool-title" x-text="onuDisplayName(toolTarget)"></h2><p><strong x-text="toolMeta?.onu?.olt_name||oltName(toolTarget.olt_id)"></strong><span x-text="' · Slot '+(toolTarget.interface||'').split('/')[1]+' / PON '+(toolTarget.interface||'').split('/')[2]?.split(':')[0]+' / ONU '+toolTarget.onu_index"></span><span class="mono" x-text="' · '+toolTarget.sn"></span></p></div></div>
            <div class="onu-tool-header-actions"><button class="btn secondary" @click="refreshOnuTool()" :disabled="toolBusy||toolMeta?.source!=='real'"><i data-lucide="refresh-cw" :class="{'spinning':toolBusy}"></i><span x-text="toolBusy?(toolApplying?'Menerapkan…':'Membaca…'):'Refresh konfigurasi'"></span></button><button class="icon-button" aria-label="Tutup ONU Configuration Tool" @click="closeOnuTool()" :disabled="toolApplying"><i data-lucide="x"></i></button></div>
        </header>
        <nav class="onu-tool-tabs" role="tablist" aria-label="ONU Configuration Tool"><template x-for="(tab,index) in toolTabs" :key="tab.key"><button role="tab" :id="'tool-tab-'+tab.key" :aria-label="tab.label" aria-controls="onu-tool-content" :aria-selected="toolTab===tab.key" :tabindex="toolTab===tab.key?0:-1" @click="selectToolTab(tab.key)" @keydown="toolTabKey($event,index)" :disabled="toolApplying"><span x-text="tab.label"></span><small x-show="toolState[tab.key]?.length" x-text="toolState[tab.key]?.length"></small></button></template></nav>
        <div class="onu-tool-body" id="onu-tool-content" role="tabpanel" :aria-labelledby="'tool-tab-'+toolTab">
            <div class="onu-tool-status"><span><span class="dot" :class="toolSnapshot?'green':'amber'"></span><span x-text="toolSnapshot?.observed_at?'Konfigurasi perangkat · '+dateTime(toolSnapshot.observed_at):'Belum ada pembacaan konfigurasi'"></span></span><span class="status-badge" x-text="toolMeta?.source==='real'?'OLT REAL':'MODE SIMULATOR'"></span></div>
            <p class="onu-detail-error" role="alert" x-show="toolError" x-text="toolError"></p>
            <p class="notice" role="status" x-show="toolNotice" x-text="toolNotice"></p>
            <p class="notice" x-show="toolMeta?.source&&toolMeta.source!=='real'">Konfigurasi lanjutan memerlukan OLT dalam mode real.</p>
            <template x-for="warning in toolProfiles.warnings||[]" :key="warning"><p class="notice" x-text="warning"></p></template>
            <div class="onu-tool-wan-modes" role="group" aria-label="Mode WAN IP" x-show="toolTab==='wan'"><template x-for="mode in [{key:'static',label:'Static IP'},{key:'pppoe',label:'PPPoE'},{key:'dhcp',label:'DHCP'},{key:'remote',label:'Remote Access'}]" :key="mode.key"><button class="btn secondary" :class="{'tool-mode-active':toolWanMode===mode.key}" :aria-pressed="toolWanMode===mode.key" @click="selectToolWan(mode.key)" :disabled="toolApplying" x-text="mode.label"></button></template></div>
            @include('partials.skeleton',['show'=>'toolBusy&&!toolSnapshot'])
            <div class="onu-tool-layout" x-show="!toolBusy||toolSnapshot" :aria-busy="toolBusy">
                <div class="onu-tool-overview">
                    <section class="onu-tool-card"><div class="onu-tool-card-heading"><div><p class="eyebrow">KONFIGURASI PERANGKAT</p><h3 x-text="toolTitle+' Saat Ini'"></h3></div><span class="count-pill" x-text="toolRows.length"></span></div>
                        <div class="table-scroll"><table class="onu-tool-table"><thead><tr><template x-for="column in toolColumns" :key="column[0]"><th x-text="column[1]"></th></template><th>Aksi</th></tr></thead><tbody><template x-for="(row,index) in toolRows" :key="row.port||row.id||row.name||index"><tr><template x-for="column in toolColumns" :key="column[0]"><td><span :class="{'mono':['id','vlan','ip','gem_id','tcont_id'].includes(column[0]),'status-badge':column[0]==='status'}" x-text="toolCell(row,column[0])"></span></td></template><td class="onu-tool-row-actions"><button type="button" class="text-button" @click="editToolRow(row)" :disabled="toolBusy||!db.permissions.operate||row.type==='other'" :aria-label="'Edit '+toolTitle+' '+(row.port||row.id||row.name)"><i data-lucide="pencil"></i>Edit</button><button type="button" class="text-button red-text" x-show="toolKind!=='ports'||row._configured" @click="previewToolChange('delete',row)" :disabled="toolBusy||!db.permissions.operate||row.type==='other'" :aria-label="'Hapus '+toolTitle+' '+(row.port||row.id||row.name)"><i data-lucide="trash-2"></i>Hapus</button></td></tr></template></tbody></table></div>
                        <p class="onu-tool-empty muted" x-show="!toolRows.length" x-text="toolSnapshot?'Belum ada '+toolTitle+' yang dikonfigurasi.':'Data konfigurasi belum tersedia. Gunakan Refresh konfigurasi untuk membaca OLT.'"></p>
                    </section>
                    <template x-if="toolTab==='wan'"><div class="onu-tool-profile-grid"><template x-for="group in [{key:'vlan',title:'VLAN Profiles'},{key:'ip',title:'IP Profiles'}]" :key="group.key"><section class="onu-tool-card"><div class="onu-tool-card-heading"><h3 x-text="group.title"></h3><span class="count-pill" x-text="(toolProfiles[group.key]||[]).length"></span></div><ul class="onu-tool-profile-list"><template x-for="profile in toolProfiles[group.key]||[]" :key="profile.name"><li><strong x-text="profile.name"></strong><span class="mono muted" x-text="profile.vlan?'VLAN '+profile.vlan:profile.gateway||'Profil perangkat'"></span></li></template></ul><p class="onu-tool-empty muted" x-show="!(toolProfiles[group.key]||[]).length">Belum ada profil terbaca.</p></section></template></div></template>
                    <aside class="onu-tool-guide"><i data-lucide="info"></i><div><h4 x-text="'Tentang '+toolTitle"></h4><p x-text="toolGuide"></p></div></aside>
                    <p class="small muted" x-show="toolKind==='gem'&&toolForm.traffic_type==='multicast'">GEM untuk IPTV memakai T-CONT dan profil downstream yang dipilih. VLAN serta IGMP multicast pada OLT perlu sudah tersedia; tool ini tidak mengubah konfigurasi multicast global.</p>
                </div>
                <form x-ref="onuToolForm" class="onu-tool-card onu-tool-form" @submit.prevent="previewToolChange()" @input="toolPlan=null" @change="toolPlan=null">
                    <div class="onu-tool-card-heading"><div><p class="eyebrow" x-text="toolEditing?'EDIT KONFIGURASI':'TAMBAH KONFIGURASI'"></p><h3 x-text="(toolEditing?'Edit ':toolKind==='ports'?'Konfigurasi Port':'Tambahkan ')+(toolKind==='ports'?'':toolTitle+(toolEditing?'':' Baru'))"></h3></div><i data-lucide="plus" x-show="!toolEditing"></i></div>
                    <fieldset :disabled="toolBusy||!db.permissions.operate||toolMeta?.source!=='real'||!toolSnapshot"><div class="onu-tool-fields">
                        <template x-for="field in toolFields" :key="toolKind+'-'+field.key"><label :class="{'onu-tool-checkbox':field.type==='checkbox'}"><span x-text="field.label"></span>
                            <template x-if="field.type==='select'"><select :aria-label="field.label" x-model="toolForm[field.key]" :required="field.required" :disabled="toolEditing&&(['id','port_type','port_id'].includes(field.key)||toolKind==='onu_service'&&field.key==='name')" @change="if(field.key==='uni_type')toolForm.uni=toolForm.uni_type==='ethuni'?'eth_0/1':'1'"><option value="" x-text="field.required?'Pilih '+field.label:'Tanpa perubahan profil'"></option><template x-for="option in toolOptions(field.key)" :key="String(option.value)"><option :value="option.value" x-text="option.label"></option></template></select></template>
                            <template x-if="field.type!=='select'"><input :aria-label="field.label" :type="field.type" x-model="toolForm[field.key]" :required="field.required" :min="field.min" :max="field.max" :maxlength="field.type==='password'?64:field.key==='acs_url'?128:field.key==='description'?80:64" :disabled="toolEditing&&toolKind==='onu_service'&&field.key==='name'" :placeholder="field.type==='password'&&toolEditing?'Kosongkan untuk mempertahankan password':''" :autocomplete="field.type==='password'?'new-password':'off'" spellcheck="false"></template>
                        </label></template>
                    </div><div class="onu-tool-form-actions"><button class="btn primary" type="submit"><i data-lucide="plus" x-show="!toolEditing"></i><span x-text="toolEditing?'Pratinjau Perubahan':toolKind==='ports'?'Pratinjau Konfigurasi':toolKind==='tr069'?'Configure TR069':'Tambah '+toolTitle"></span></button><button class="btn secondary" type="button" @click="resetToolForm()" x-show="toolEditing">Batal edit</button></div></fieldset>
                    <p class="small muted">Perubahan diterapkan setelah pratinjau diperiksa. Hasil akan dibaca ulang dari OLT.</p>
                </form>
            </div>
            <section class="onu-tool-card onu-tool-preview" x-ref="onuToolPreview" x-show="toolPlan"><div class="onu-tool-card-heading"><div><p class="eyebrow">PRATINJAU PERUBAHAN</p><h3 x-text="toolPlan?.action==='delete'?'Hapus '+toolTitle:'Terapkan '+toolTitle"></h3></div><span class="status-badge">Rahasia disamarkan</span></div><pre x-text="toolPlan?.commands?.join('\n')||''"></pre><div class="onu-tool-preview-footer"><p class="small muted">Perubahan diterapkan ke running config dan dapat memengaruhi layanan ONU. Pratinjau berlaku 5 menit.</p><div><button class="btn secondary" @click="toolPlan=null" :disabled="toolBusy">Batal</button><button class="btn" :class="toolPlan?.action==='delete'?'danger-solid':'primary'" @click="applyToolChange()" :disabled="toolBusy" x-text="toolApplying?'Menerapkan…':'Terapkan ke OLT'"></button></div></div></section>
        </div>
    </div></template>
</dialog>
